import{_ as e,a as t,b as a,c as n,d as r,e as s}from"./chunks/wb-universe-settings-region.BXG2sqQw.js";import{_ as i,c as l,o as g,ae as u}from"./chunks/framework.DBgX5bsf.js";const C=JSON.parse('{"title":"Theme Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/configuration-theme.md","filePath":"en/docs/configuration-theme.md"}'),c={name:"en/docs/configuration-theme.md"};function d(p,o,h,f,m,b){return g(),l("div",null,o[0]||(o[0]=[u('<h1 id="theme-configuration" tabindex="-1">Theme Configuration <a class="header-anchor" href="#theme-configuration" aria-label="Permalink to &quot;Theme Configuration&quot;">​</a></h1><p>The <strong>E-commerce Sale of Bags (ESB)</strong> theme is a Drupal theme offering advanced configuration options to customize the appearance of your site. This theme provides <strong>10 regions</strong>, enabling the creation of complex layouts. You can configure colors, fonts, text sizes, layout options, and much more by following the advanced configuration guide.<br> To access the theme configuration options, go to <code>admin/appearance/settings/habeuk_theme</code>.<br><em>This theme inherits its configuration from the <a href="https://www.drupal.org/project/wb_universe" target="_blank" rel="noreferrer">Wb Universe</a> theme.</em></p><h3 id="adding-google-analytics-and-facebook-api-keys" tabindex="-1">Adding Google Analytics and Facebook API Keys <a class="header-anchor" href="#adding-google-analytics-and-facebook-api-keys" aria-label="Permalink to &quot;Adding Google Analytics and Facebook API Keys&quot;">​</a></h3><ol><li>Create a <strong>Google Analytics</strong> and <strong>Facebook API</strong> account to obtain access keys.</li><li>Add these keys in the designated fields in the administration interface.<br><img src="'+e+'" alt="Google Analytics and Facebook API"></li></ol><h3 id="configuration-group-page-templates" tabindex="-1">Configuration Group: <strong>Page Templates</strong> <a class="header-anchor" href="#configuration-group-page-templates" aria-label="Permalink to &quot;Configuration Group: **Page Templates**&quot;">​</a></h3><p>This group allows you to configure page options, including container sizes for different pages. It is divided into <strong>4 subgroups</strong>, each containing page links and a <strong>&quot;Select container&quot;</strong> field.<br> The <strong>&quot;Select container&quot;</strong> field offers 4 size options:</p><ul><li><strong>Container</strong>: Medium display (approximately 1200px).</li><li><strong>Container-fluid</strong>: Wide display.</li><li><strong>Width-tablette</strong>: Medium display optimized for tablets (ideal for content pages).</li><li><strong>Width-phone</strong>: Medium display optimized for mobile devices.</li></ul><p><img src="'+t+'" alt="Wb Universe Page Templates Settings"></p><h3 id="configuration-group-layout" tabindex="-1">Configuration Group: <strong>Layout</strong> <a class="header-anchor" href="#configuration-group-layout" aria-label="Permalink to &quot;Configuration Group: **Layout**&quot;">​</a></h3><p>This group allows you to configure the display of side columns (left or right) on your pages. You can also define column sizes using <strong>Bootstrap</strong> classes or custom <strong>CSS</strong> classes (you must create the styles associated with these classes).<br><img src="'+a+'" alt="Wb Universe Layout Settings"></p><h3 id="configuration-group-forms" tabindex="-1">Configuration Group: <strong>Forms</strong> <a class="header-anchor" href="#configuration-group-forms" aria-label="Permalink to &quot;Configuration Group: **Forms**&quot;">​</a></h3><p>This group allows you to add <strong>CSS</strong> classes to your forms. For example, you can add the Bootstrap class <strong><code>mb-4</code></strong> to apply a bottom margin.<br><img src="'+n+'" alt="Wb Universe Form Settings"></p><h3 id="configuration-group-menu-display" tabindex="-1">Configuration Group: <strong>Menu Display</strong> <a class="header-anchor" href="#configuration-group-menu-display" aria-label="Permalink to &quot;Configuration Group: **Menu Display**&quot;">​</a></h3><p>This group allows you to configure menu display. You can choose between a <strong>horizontal</strong> (default) or <strong>vertical</strong> display.<br> For a vertical display, add the <strong><code>flex-column</code></strong> or <strong><code>navbar-nav</code></strong> class in the <strong>&quot;Class menu&quot;</strong> field.<br><img src="'+r+'" alt="Wb Universe Menu Display Settings"></p><h3 id="configuration-group-region-css-classes" tabindex="-1">Configuration Group: <strong>Region CSS Classes</strong> <a class="header-anchor" href="#configuration-group-region-css-classes" aria-label="Permalink to &quot;Configuration Group: **Region CSS Classes**&quot;">​</a></h3><p>This group allows you to add custom <strong>CSS</strong> classes to each of your regions.<br><img src="'+s+'" alt="Wb Universe Region Settings"></p><h3 id="configuration-group-table-configuration" tabindex="-1">Configuration Group: <strong>Table Configuration</strong> <a class="header-anchor" href="#configuration-group-table-configuration" aria-label="Permalink to &quot;Configuration Group: **Table Configuration**&quot;">​</a></h3><p>This group allows you to add <strong>CSS</strong> classes to tables.</p><ul><li>For the <strong>&quot;Custom class for tag table&quot;</strong> field, you can add the classes <strong><code>mb-4 table table-striped</code></strong>.</li><li>For the <strong>&quot;Custom class for container&quot;</strong> field, you can add the classes <strong><code>border border-radius-10 px-5 py-4 mb-4</code></strong>.</li></ul><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>The <strong>E-commerce Sale of Bags (ESB)</strong> theme offers great flexibility to customize the appearance and structure of your site. You can adjust colors, font sizes, and many other settings by exploring the available options. For additional customizations, consult the theme&#39;s advanced settings.</p>',21)]))}const q=i(c,[["render",d]]);export{C as __pageData,q as default};
